#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <mutex>
#include <thread>
#include <atomic>
#include <functional>
#include <chrono>
#include <algorithm>

enum class Role { GUEST = 0, USER = 1, MODERATOR = 2, ADMIN = 3 };

struct Session {
    std::string username;
    Role role;
    int privilege_tokens;
    std::chrono::steady_clock::time_point last_action;
    bool in_transaction;
};

class PrivilegePool {
private:
    std::atomic<int> available_tokens{1000};
    std::mutex ledger_mutex;
    std::unordered_map<std::string, int> ledger;

public:
    bool borrow_tokens(const std::string& user, int amount) {
        if (amount > available_tokens.load()) return false;
        available_tokens.fetch_sub(amount);
        std::lock_guard<std::mutex> lock(ledger_mutex);
        ledger[user] += amount;
        return true;
    }

    bool return_tokens(const std::string& user, int amount) {
        std::lock_guard<std::mutex> lock(ledger_mutex);
        if (ledger.find(user) == ledger.end()) return false;
        if (ledger[user] < amount) return false;
        ledger[user] -= amount;
        available_tokens.fetch_add(amount);
        return true;
    }

    int get_balance(const std::string& user) {
        std::lock_guard<std::mutex> lock(ledger_mutex);
        return ledger.count(user) ? ledger[user] : 0;
    }
};

class ChatServer {
private:
    std::mutex sessions_mutex;
    std::unordered_map<std::string, Session> sessions;
    PrivilegePool pool;
    std::vector<std::string> audit_log;
    std::mutex audit_mutex;

    void log_action(const std::string& action) {
        std::lock_guard<std::mutex> lock(audit_mutex);
        audit_log.push_back(action);
    }

    Role compute_effective_role(const Session& s) {
        int total = s.privilege_tokens + pool.get_balance(s.username);
        if (total >= 100) return Role::ADMIN;
        if (total >= 50) return Role::MODERATOR;
        if (total >= 10) return Role::USER;
        return Role::GUEST;
    }

    bool validate_transaction_state(const Session& s) {
        auto now = std::chrono::steady_clock::now();
        auto elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(
            now - s.last_action).count();
        return elapsed < 5000;
    }

public:
    bool create_session(const std::string& username, Role initial_role) {
        std::lock_guard<std::mutex> lock(sessions_mutex);
        if (sessions.count(username)) return false;
        sessions[username] = {username, initial_role, 0,
                             std::chrono::steady_clock::now(), false};
        log_action("SESSION_CREATE: " + username);
        return true;
    }

    bool begin_privilege_transaction(const std::string& username) {
        std::lock_guard<std::mutex> lock(sessions_mutex);
        if (!sessions.count(username)) return false;
        sessions[username].in_transaction = true;
        sessions[username].last_action = std::chrono::steady_clock::now();
        return true;
    }

    bool request_temporary_elevation(const std::string& username, int tokens) {
        std::lock_guard<std::mutex> lock(sessions_mutex);
        if (!sessions.count(username)) return false;
        Session& s = sessions[username];
        if (!s.in_transaction) return false;
        if (!validate_transaction_state(s)) {
            s.in_transaction = false;
            return false;
        }
        if (!pool.borrow_tokens(username, tokens)) return false;
        s.privilege_tokens += tokens;
        s.role = compute_effective_role(s);
        log_action("ELEVATE: " + username + " +" + std::to_string(tokens));
        return true;
    }

    bool execute_privileged_action(const std::string& username,
                                   const std::string& action,
                                   const std::string& target) {
        std::lock_guard<std::mutex> lock(sessions_mutex);
        if (!sessions.count(username)) return false;
        Session& s = sessions[username];
        Role effective = compute_effective_role(s);
        if (action == "kick" && effective >= Role::MODERATOR) {
            log_action("KICK: " + username + " -> " + target);
            sessions.erase(target);
            return true;
        }
        if (action == "grant_admin" && effective >= Role::ADMIN) {
            if (sessions.count(target)) {
                sessions[target].role = Role::ADMIN;
                sessions[target].privilege_tokens = 100;
                log_action("GRANT_ADMIN: " + username + " -> " + target);
                return true;
            }
        }
        return false;
    }

    bool commit_privilege_transaction(const std::string& username) {
        std::lock_guard<std::mutex> lock(sessions_mutex);
        if (!sessions.count(username)) return false;
        Session& s = sessions[username];
        if (!s.in_transaction) return false;
        int borrowed = pool.get_balance(username);
        pool.return_tokens(username, borrowed);
        s.privilege_tokens -= borrowed;
        s.in_transaction = false;
        s.role = compute_effective_role(s);
        log_action("COMMIT: " + username + " returned " + std::to_string(borrowed));
        return true;
    }

    Role get_user_role(const std::string& username) {
        std::lock_guard<std::mutex> lock(sessions_mutex);
        if (!sessions.count(username)) return Role::GUEST;
        return sessions[username].role;
    }
};

int main() {
    ChatServer server;
    server.create_session("alice", Role::GUEST);
    server.create_session("bob", Role::USER);

    server.begin_privilege_transaction("alice");
    server.request_temporary_elevation("alice", 100);
    server.execute_privileged_action("alice", "grant_admin", "alice");
    server.commit_privilege_transaction("alice");

    std::cout << "Alice role after commit: " << static_cast<int>(server.get_user_role("alice")) << std::endl;
    return 0;
}
